    arg_types = {"keys": True, "values": True}
    is_var_len_args = True
    var_len_arg_key = "values"

    @property
    def keys(self) -> list[Expr]:
        return self.args["keys"].expressions

    @property
    def values(self) -> list[Expr]:
        return self.args["values"].expressions


