from __future__ import annotations


from sqlglot import exp, generator, transforms
from sqlglot.dialects.dialect import rename_func, strposition_sql as _strposition_sql


class TableauGenerator(generator.Generator):
    SELECT_KINDS = ()
    TRY_SUPPORTED = False
    SUPPORTS_UESCAPE = False
    SUPPORTS_DECODE_CASE = False

    AFTER_HAVING_MODIFIER_TRANSFORMS = generator.AFTER_HAVING_MODIFIER_TRANSFORMS

    JOIN_HINTS = False
    TABLE_HINTS = False
    QUERY_HINTS = False

    TRANSFORMS = {
        **generator.Generator.TRANSFORMS,
        exp.Coalesce: rename_func("IFNULL"),
        exp.Select: transforms.preprocess([transforms.eliminate_distinct_on]),
    }

    PROPERTIES_LOCATION = {
        **generator.Generator.PROPERTIES_LOCATION,
        exp.VolatileProperty: exp.Properties.Location.UNSUPPORTED,
    }

    def if_sql(self, expression: exp.If) -> str:
        this = self.sql(expression, "this")
        true = self.sql(expression, "true")
        false = self.sql(expression, "false")
        return f"IF {this} THEN {true} ELSE {false} END"

    def count_sql(self, expression: exp.Count) -> str:
        this = expression.this
        if isinstance(this, exp.Distinct):
            return self.func("COUNTD", *this.expressions)
        return self.func("COUNT", this)

    def strposition_sql(self, expression: exp.StrPosition) -> str:
        has_occurrence = "occurrence" in expression.args
        return _strposition_sql(
            self,
            expression,
            func_name="FINDNTH" if has_occurrence else "FIND",
            supports_occurrence=has_occurrence,
        )

sqlglot/generators/teradata.py.source:
from __future__ import annotations

import typing as t
from decimal import Decimal

from sqlglot import exp, generator, transforms
from sqlglot.dialects.dialect import (
    date_trunc_to_trunc_sql,
    max_or_greatest,
    min_or_least,
    rename_func,
    strposition_sql,
    to_number_with_nls_param,
)
from sqlglot.parsers.teradata import is_window_aggregate
from collections import defaultdict


def _date_add_sql(
    kind: t.Literal["+", "-"],
) -> t.Callable[[TeradataGenerator, exp.DateAdd | exp.DateSub], str]:
    def func(self: TeradataGenerator, expression: exp.DateAdd | exp.DateSub) -> str:
        this = self.sql(expression, "this")
        unit = expression.args.get("unit")
        value = self._simplify_unless_literal(expression.expression)

        if not isinstance(value, exp.Literal):
            self.unsupported("Cannot add non literal")

        if isinstance(value, exp.Neg):
            kind_to_op = {"+": "-", "-": "+"}
            value = exp.Literal.string(value.this.to_py())
        else:
            kind_to_op = {"+": "+", "-": "-"}
            value.set("is_string", True)

        return f"{this} {kind_to_op[kind]} {self.sql(exp.Interval(this=value, unit=unit))}"

    return func


class TeradataGenerator(generator.Generator):
    SELECT_KINDS = ()
    TRY_SUPPORTED = False
    SUPPORTS_UESCAPE = False
    SUPPORTS_DECODE_CASE = False

    AFTER_HAVING_MODIFIER_TRANSFORMS = generator.AFTER_HAVING_MODIFIER_TRANSFORMS
    MOD_OPERATOR = "MOD"
    MOD_PAREN_PARENT_TYPES = (*generator.Generator.MOD_PAREN_PARENT_TYPES, exp.Pow)

    LIMIT_IS_TOP = True
    SET_OP_LIMITS = True
    JOIN_HINTS = False
    TABLE_HINTS = False
    QUERY_HINTS = False
    TABLESAMPLE_KEYWORDS = "SAMPLE"
    LAST_DAY_SUPPORTS_DATE_PART = False
    CAN_IMPLEMENT_ARRAY_ANY = True
    TZ_TO_WITH_TIME_ZONE = True
    ARRAY_SIZE_NAME = "CARDINALITY"

    TYPE_MAPPING = {
        **generator.Generator.TYPE_MAPPING,
        exp.DType.GEOMETRY: "ST_GEOMETRY",
        exp.DType.DOUBLE: "DOUBLE PRECISION",
        exp.DType.TINYINT: "BYTEINT",
        exp.DType.TIMESTAMPTZ: "TIMESTAMP",
    }

    PROPERTIES_LOCATION = {
        **generator.Generator.PROPERTIES_LOCATION,
        exp.OnCommitProperty: exp.Properties.Location.POST_INDEX,
        exp.PartitionedByProperty: exp.Properties.Location.POST_EXPRESSION,
        exp.StabilityProperty: exp.Properties.Location.POST_CREATE,
    }

    TRANSFORMS = {
        **generator.Generator.TRANSFORMS,
        exp.ArgMax: rename_func("MAX_BY"),
        exp.ArgMin: rename_func("MIN_BY"),
        exp.Max: max_or_greatest,
        exp.Min: min_or_least,
        exp.Pow: lambda self, e: self.binary(e, "**"),
        exp.Rand: lambda self, e: self.func("RANDOM", e.args.get("lower"), e.args.get("upper")),
        exp.Select: transforms.preprocess(
            [transforms.eliminate_distinct_on, transforms.eliminate_semi_and_anti_joins]
        ),
        exp.StrPosition: lambda self, e: strposition_sql(
            self, e, func_name="INSTR", supports_position=True, supports_occurrence=True
        ),
        exp.StrToDate: lambda self, e: (
            f"CAST({self.sql(e, 'this')} AS DATE FORMAT {self.format_time(e)})"
        ),
        exp.ToChar: lambda self, e: self.function_fallback_sql(e),
        exp.ToNumber: to_number_with_nls_param,
        exp.Use: lambda self, e: f"DATABASE {self.sql(e, 'this')}",
        exp.DateTrunc: date_trunc_to_trunc_sql,
        exp.DateAdd: _date_add_sql("+"),
        exp.DateSub: _date_add_sql("-"),
        exp.DayOfWeek: rename_func("DAYOFWEEK"),
        exp.Quarter: lambda self, e: self.sql(exp.Extract(this="QUARTER", expression=e.this)),
    }

    def hexstring_sql(
        self, expression: exp.HexString, binary_function_repr: str | None = None
    ) -> str:
        if expression.args.get("is_character"):
            return f"{self.sql(exp.Literal.string(expression.this))}XC"
        return super().hexstring_sql(expression, binary_function_repr)

    def execute_sql(self, expression: exp.Execute) -> str:
        if expression.args.get("return_status"):
            self.unsupported("Teradata EXECUTE does not support a return status")
        this = self.sql(expression, "this")
        arguments = f"({self.expressions(expression, flat=True)})" if expression.expressions else ""
        return f"EXECUTE {this}{arguments}"

    def currenttime_sql(self, expression: exp.CurrentTime) -> str:
        prefix, suffix = ("(", ")") if expression.this else ("", "")
        return self.func("CURRENT_TIME", expression.this, prefix=prefix, suffix=suffix)

    def currenttimestamp_sql(self, expression: exp.CurrentTimestamp) -> str:
        prefix, suffix = ("(", ")") if expression.this else ("", "")
        return self.func("CURRENT_TIMESTAMP", expression.this, prefix=prefix, suffix=suffix)

    def teradatatitle_sql(self, expression: exp.TeradataTitle) -> str:
        return f"{self.sql(expression, 'this')} (TITLE {self.sql(expression, 'title')})"

    def teradatanamed_sql(self, expression: exp.TeradataNamed) -> str:
        return f"{self.sql(expression, 'this')} (NAMED {self.sql(expression, 'alias')})"

    def cast_sql(self, expression: exp.Cast, safe_prefix: str | None = None) -> str:
        if expression.to.this == exp.DType.UNKNOWN and expression.args.get("format"):
            # We don't actually want to print the unknown type in CAST(<value> AS FORMAT <format>)
            expression.to.pop()

        return super().cast_sql(expression, safe_prefix=safe_prefix)

    def trycast_sql(self, expression: exp.TryCast) -> str:
        return self.cast_sql(expression, safe_prefix="TRY")

    def tablesample_sql(
        self,
        expression: exp.TableSample,
        tablesample_keyword: str | None = None,
    ) -> str:
        sample = expression.args.get("size")
        percent = expression.args.get("percent")
        if percent and percent.is_number:
            fraction = Decimal(percent.to_py()).scaleb(-2)
            # 100 percent keeps its decimal point, otherwise it'd be read back as a row count
            sample = exp.Literal.number(
                format(fraction.normalize() if fraction < 1 else fraction, "f")
            )

        return f" SAMPLE {self.sql(sample) or self.expressions(expression)}"

    def window_sql(self, expression: exp.Window) -> str:
        spec = expression.args.get("spec")

        if (
            spec
            and expression.args.get("order")
            and is_window_aggregate(expression)
            and spec.text("kind").upper() == "ROWS"
            and spec.text("start").upper() == "UNBOUNDED"
            and spec.text("start_side").upper() == "PRECEDING"
            and spec.text("end").upper() == "UNBOUNDED"
            and spec.text("end_side").upper() == "FOLLOWING"
        ):
            # This is the default frame of window aggregates with ORDER BY in Teradata
            expression.set("spec", None)

        return super().window_sql(expression)

    def partitionedbyproperty_sql(self, expression: exp.PartitionedByProperty) -> str:
        return f"PARTITION BY {self.sql(expression, 'this')}"

    # FROM before SET in Teradata UPDATE syntax
    # https://docs.teradata.com/r/Enterprise_IntelliFlex_VMware/Teradata-VantageTM-SQL-Data-Manipulation-Language-17.20/Statement-Syntax/UPDATE/UPDATE-Syntax-Basic-Form-FROM-Clause
    def update_sql(self, expression: exp.Update) -> str:
        this = self.sql(expression, "this")
        from_sql = self.sql(expression, "from_")
        set_sql = self.expressions(expression, flat=True)
        where_sql = self.sql(expression, "where")
        sql = f"UPDATE {this}{from_sql} SET {set_sql}{where_sql}"
        return self.prepend_ctes(expression, sql)

    def rangen_sql(self, expression: exp.RangeN) -> str:
        this = self.sql(expression, "this")
        expressions_sql = self.expressions(expression)
        each_sql = self.sql(expression, "each")
        each_sql = f" EACH {each_sql}" if each_sql else ""

        return f"RANGE_N({this} BETWEEN {expressions_sql}{each_sql})"

    def lockingstatement_sql(self, expression: exp.LockingStatement) -> str:
        """Generate SQL for LOCKING statement"""
        locking_clause = self.sql(expression, "this")
        query_sql = self.sql(expression, "expression")

        return f"{locking_clause} {query_sql}"

    def createable_sql(self, expression: exp.Create, locations: defaultdict) -> str:
        kind = self.sql(expression, "kind").upper()
        if kind == "TABLE" and locations.get(exp.Properties.Location.POST_NAME):
            this_name = self.sql(expression.this, "this")
            this_properties = self.properties(
                exp.Properties(expressions=locations[exp.Properties.Location.POST_NAME]),
                wrapped=False,
                prefix=",",
            )
            this_schema = self.schema_columns_sql(expression.this)
            return f"{this_name}{this_properties}{self.sep()}{this_schema}"

        return super().createable_sql(expression, locations)

    def extract_sql(self, expression: exp.Extract) -> str:
        this = self.sql(expression, "this")
        if this.upper() != "QUARTER":
            return super().extract_sql(expression)

        to_char = exp.func("to_char", expression.expression, exp.Literal.string("Q"))
        return self.sql(exp.cast(to_char, exp.DType.INT))

    def interval_sql(self, expression: exp.Interval) -> str:
        multiplier = 0
        unit = expression.text("unit")

        if unit.startswith("WEEK"):
            multiplier = 7
        elif unit.startswith("QUARTER"):
            multiplier = 90

        if multiplier:
            return f"({multiplier} * {super().interval_sql(exp.Interval(this=expression.this, unit=exp.var('DAY')))})"

        return super().interval_sql(expression)

sqlglot/jsonpath.py.source:
from __future__ import annotations

import typing as t

import sqlglot.expressions as exp
from sqlglot.errors import ParseError
from sqlglot.tokens import Token, Tokenizer, TokenType

if t.TYPE_CHECKING:
    from sqlglot.dialects.dialect import DialectType
    from collections.abc import Collection


class JSONPathTokenizer(Tokenizer):
    SINGLE_TOKENS = {
        "(": TokenType.L_PAREN,
        ")": TokenType.R_PAREN,
        "[": TokenType.L_BRACKET,
        "]": TokenType.R_BRACKET,
        ":": TokenType.COLON,
        ",": TokenType.COMMA,
        "-": TokenType.DASH,
        ".": TokenType.DOT,
        "?": TokenType.PLACEHOLDER,
        "@": TokenType.PARAMETER,
        "'": TokenType.QUOTE,
        '"': TokenType.QUOTE,
        "$": TokenType.DOLLAR,
        "*": TokenType.STAR,
    }

    KEYWORDS = {
        "..": TokenType.DOT,
    }

    IDENTIFIER_ESCAPES = ["\\"]
    STRING_ESCAPES = ["\\"]
    NUMBERS_CAN_HAVE_DECIMALS = False

    VAR_TOKENS = {
        TokenType.VAR,
    }


def parse(path: str, dialect: DialectType = None) -> exp.JSONPath:
    """Takes in a JSON path string and parses it into a JSONPath expression."""
    from sqlglot.dialects import Dialect

    dialect_inst = Dialect.get_or_raise(dialect)
    jsonpath_tokenizer = dialect_inst.jsonpath_tokenizer()
    tokens = jsonpath_tokenizer.tokenize(path)
    size = len(tokens)

    i = 0

    def _curr() -> TokenType | None:
        return tokens[i].token_type if i < size else None

    def _prev() -> Token:
        return tokens[i - 1]

    def _advance() -> Token:
        nonlocal i
        i += 1
        return _prev()

    def _error(msg: str) -> str:
        return f"{msg} at index {i}: {path}"

    @t.overload
    def _match(token_type: TokenType, raise_unmatched: t.Literal[True] = True) -> Token:
        pass

    @t.overload
    def _match(token_type: TokenType, raise_unmatched: t.Literal[False] = False) -> Token | None:
        pass

    def _match(token_type, raise_unmatched=False):
        if _curr() == token_type:
            return _advance()
        if raise_unmatched:
            raise ParseError(_error(f"Expected {token_type}"))
        return None

    def _match_set(types: Collection[TokenType]) -> Token | None:
        return _advance() if _curr() in types else None

    def _parse_literal() -> t.Any:
        token = _match(TokenType.STRING) or _match(TokenType.IDENTIFIER)
        if token:
            return token.text
        if _match(TokenType.STAR):
            return exp.JSONPathWildcard()
        if _match(TokenType.PLACEHOLDER) or _match(TokenType.L_PAREN):
            script = _prev().text == "("
            start = i

            while True:
                if _match(TokenType.L_BRACKET):
                    _parse_bracket()  # nested call which we can throw away
                if _curr() in (TokenType.R_BRACKET, None):
                    break
                _advance()

            expr_type = exp.JSONPathScript if script else exp.JSONPathFilter
            end = tokens[i].end if i < size else tokens[-1].end
            return expr_type(this=path[tokens[start].start : end])

        number = "-" if _match(TokenType.DASH) else ""

        token = _match(TokenType.NUMBER)
        if token:
            number += token.text

        if number:
            try:
                return int(number)
            except ValueError:
                raise ParseError(_error(f"Invalid integer index: {number}"))

        return False

    def _parse_slice() -> t.Any:
        start = _parse_literal()
        end = _parse_literal() if _match(TokenType.COLON) else None
        step = _parse_literal() if _match(TokenType.COLON) else None

        if end is None and step is None:
            return start

        return exp.JSONPathSlice(start=start, end=end, step=step)

    def _parse_bracket() -> exp.JSONPathPart:
        literal = _parse_slice()

        if isinstance(literal, str) or literal is not False:
            indexes = [literal]
            while _match(TokenType.COMMA):
                literal = _parse_slice()

                if isinstance(literal, str) or literal is not False:
                    indexes.append(literal)

            if len(indexes) == 1:
                if isinstance(indexes[0], str):
                    node: exp.JSONPathPart = exp.JSONPathKey(this=indexes[0])
                elif isinstance(indexes[0], exp.JSONPathPart) and isinstance(
                    indexes[0], (exp.JSONPathScript, exp.JSONPathFilter)
                ):
                    node = exp.JSONPathSelector(this=indexes[0])
                else:
                    node = exp.JSONPathSubscript(this=indexes[0])
            else:
                node = exp.JSONPathUnion(expressions=indexes)
        else:
            raise ParseError(_error("Cannot have empty segment"))

        _match(TokenType.R_BRACKET, raise_unmatched=True)

        return node

    def _parse_var_text() -> str:
        """
        Consumes & returns the text for a var. In BigQuery it's valid to have a key with spaces
        in it, e.g JSON_QUERY(..., '$. a b c ') should produce a single JSONPathKey(' a b c ').
        This is done by merging "consecutive" vars until a key separator is found (dot, colon etc)
        or the path string is exhausted.
        """
        prev_index = i - 2

        while _match_set(jsonpath_tokenizer.VAR_TOKENS):
            pass

        start = 0 if prev_index < 0 else tokens[prev_index].end + 1

        if i >= len(tokens):
            # This key is the last token for the path, so it's text is the remaining path
            text = path[start:]
        else:
            text = path[start : tokens[i].start]

        return text

    # We canonicalize the JSON path AST so that it always starts with a
    # "root" element, so paths like "field" will be generated as "$.field"
    _match(TokenType.DOLLAR)
    expressions: list[exp.JSONPathPart] = [exp.JSONPathRoot()]

    while _curr():
        if _match(TokenType.DOT) or _match(TokenType.COLON):
            recursive = _prev().text == ".."

            if _match_set(jsonpath_tokenizer.VAR_TOKENS):
                value: str | exp.JSONPathWildcard | None = _parse_var_text()
            elif _match(TokenType.IDENTIFIER):
                value = _prev().text
            elif _match(TokenType.STAR):
                value = exp.JSONPathWildcard()
            else:
                value = None

            if recursive:
                expressions.append(exp.JSONPathRecursive(this=value))
            elif value:
                expressions.append(exp.JSONPathKey(this=value))
            elif not dialect_inst.JSON_PATH_SINGLE_DOT_IS_WILDCARD:
                raise ParseError(_error("Expected key name or * after DOT"))
        elif _match(TokenType.L_BRACKET):
            expressions.append(_parse_bracket())
        elif _match_set(jsonpath_tokenizer.VAR_TOKENS):
            expressions.append(exp.JSONPathKey(this=_parse_var_text()))
        elif _match(TokenType.IDENTIFIER):
            expressions.append(exp.JSONPathKey(this=_prev().text))
        elif _match(TokenType.STAR):
            expressions.append(exp.JSONPathWildcard())
        else:
            raise ParseError(_error(f"Unexpected {tokens[i].token_type}"))

    return exp.JSONPath(expressions=expressions)


JSON_PATH_PART_TRANSFORMS: dict[type[exp.Expr], t.Callable[..., str]] = {
    exp.JSONPathFilter: lambda _, e: f"?{e.this}",
    exp.JSONPathKey: lambda self, e: self._jsonpathkey_sql(e),
    exp.JSONPathRecursive: lambda _, e: f"..{e.this or ''}",
    exp.JSONPathRoot: lambda *_: "$",
    exp.JSONPathScript: lambda _, e: f"({e.this}",
    exp.JSONPathSelector: lambda self, e: f"[{self.json_path_part(e.this)}]",
    exp.JSONPathSlice: lambda self, e: ":".join(
        "" if p is False else self.json_path_part(p)
        for p in [e.args.get("start"), e.args.get("end"), e.args.get("step")]
        if p is not None
    ),
    exp.JSONPathSubscript: lambda self, e: self._jsonpathsubscript_sql(e),
    exp.JSONPathUnion: lambda self, e: (
        f"[{','.join(self.json_path_part(p) for p in e.expressions)}]"
    ),
    exp.JSONPathWildcard: lambda *_: "*",
}

ALL_JSON_PATH_PARTS = set(JSON_PATH_PART_TRANSFORMS)

sqlglot/optimizer/annotate_types.py.source:
from __future__ import annotations

import functools
import logging
import typing as t

from sqlglot import exp
from sqlglot.dialects.dialect import Dialect
from sqlglot.helper import (
    ensure_list,
    is_date_unit,
    is_iso_date,
    is_iso_datetime,
    seq_get,
)
from sqlglot.errors import OptimizeError
from sqlglot.optimizer.scope import Scope, traverse_scope
from sqlglot.schema import MappingSchema, Schema, ensure_schema

if t.TYPE_CHECKING:
    from sqlglot._typing import B, E

    # TODO (mypyc): should be -> exp.DType but some coercion lambdas return DataType
    # (e.g. l.type). The original code used t.cast(exp.DType, ...) to satisfy mypy, but
    # mypyc enforces t.cast at runtime, rejecting DataType values. Widened to accept both.
    BinaryCoercionFunc = t.Callable[
        [exp.Expr, exp.Expr], t.Optional[t.Union[exp.DataType, exp.DType]]
    ]
    BinaryCoercions = dict[tuple[exp.DType, exp.DType], BinaryCoercionFunc]

    from sqlglot.dialects.dialect import DialectType
    from sqlglot.typing import ExprMetadataType

logger = logging.getLogger("sqlglot")

# EXTRACT/DATE_PART specifiers that return BIGINT instead of INT
BIGINT_EXTRACT_DATE_PARTS = {
    "EPOCH_SECOND",
    "EPOCH_MILLISECOND",
    "EPOCH_MICROSECOND",
    "EPOCH_NANOSECOND",
    "NANOSECOND",
}


def annotate_types(
    expression: E,
    schema: dict[str, object] | Schema | None = None,
    expression_metadata: ExprMetadataType | None = None,
    coerces_to: dict[exp.DType, set[exp.DType]] | None = None,
    dialect: DialectType = None,
    overwrite_types: bool = True,
) -> E:
    """
    Infers the types of an expression, annotating its AST accordingly.

    Example:
        >>> import sqlglot
        >>> schema = {"y": {"cola": "SMALLINT"}}
        >>> sql = "SELECT x.cola + 2.5 AS cola FROM (SELECT y.cola AS cola FROM y AS y) AS x"
        >>> annotated_expr = annotate_types(sqlglot.parse_one(sql), schema=schema)
        >>> annotated_expr.expressions[0].type.this  # Get the type of "x.cola + 2.5 AS cola"
        <DType.DOUBLE: 'DOUBLE'>

    Args:
        expression: Expr to annotate.
        schema: Database schema.
        expression_metadata: Maps expression type to corresponding annotation function.
        coerces_to: Maps expression type to set of types that it can be coerced into.
        dialect: The dialect to consult when constructing a Schema object, if needed.
        overwrite_types: Re-annotate the existing AST types.

    Returns:
        The expression annotated with types.
    """

    schema = ensure_schema(schema, dialect=dialect)

    return TypeAnnotator(
        schema=schema,
        expression_metadata=expression_metadata,
        coerces_to=coerces_to,
        overwrite_types=overwrite_types,
    ).annotate(expression)


def _coerce_date_literal(l: exp.Expr, unit: exp.Expr | None) -> exp.DType:
    date_text = l.name
    is_iso_date_ = is_iso_date(date_text)

    if is_iso_date_ and is_date_unit(unit):
        return exp.DType.DATE

    # An ISO date is also an ISO datetime, but not vice versa
    if is_iso_date_ or is_iso_datetime(date_text):
        return exp.DType.DATETIME

    return exp.DType.UNKNOWN


def _coerce_date(l: exp.Expr, unit: exp.Expr | None) -> exp.DataType | exp.DType:
    if l.is_type(exp.DType.DATE) and not is_date_unit(unit):
        return exp.DType.DATETIME
    return l.type or exp.DType.UNKNOWN


def swap_args(func: BinaryCoercionFunc) -> BinaryCoercionFunc:
    @functools.wraps(func)
    def _swapped(l: exp.Expr, r: exp.Expr) -> exp.DataType | exp.DType | None:
        return func(r, l)

    return _swapped


def swap_all(coercions: BinaryCoercions) -> BinaryCoercions:
    return {**coercions, **{(b, a): swap_args(func) for (a, b), func in coercions.items()}}


def _build_coerces_to() -> dict[exp.DType, set[exp.DType]]:
    # Highest-to-lowest type precedence, as specified in Spark's docs (ANSI):
    # https://spark.apache.org/docs/3.2.0/sql-ref-ansi-compliance.html
    text_precedence = (
        exp.DType.TEXT,
        exp.DType.NVARCHAR,
        exp.DType.VARCHAR,
        exp.DType.NCHAR,
        exp.DType.CHAR,
    )
    numeric_precedence = (
        exp.DType.DECFLOAT,
        exp.DType.DOUBLE,
        exp.DType.FLOAT,
        exp.DType.BIGDECIMAL,
        exp.DType.DECIMAL,
        exp.DType.BIGINT,
        exp.DType.INT,
        exp.DType.SMALLINT,
        exp.DType.TINYINT,
    )
    timelike_precedence = (
        exp.DType.TIMESTAMPLTZ,
        exp.DType.TIMESTAMPTZ,
        exp.DType.TIMESTAMP,
        exp.DType.DATETIME,
        exp.DType.DATE,
    )

    result: dict[exp.DType, set[exp.DType]] = {}
    for type_precedence in (text_precedence, numeric_precedence, timelike_precedence):
        coerces_to: set[exp.DType] = set()
        for data_type in type_precedence:
            result[data_type] = coerces_to.copy()
            coerces_to |= {data_type}
    return result


_COERCES_TO = _build_coerces_to()


class TypeAnnotator:
    NESTED_TYPES: t.ClassVar = {
        exp.DType.ARRAY,
    }

    # Specifies what types a given type can be coerced into
    COERCES_TO: t.ClassVar[dict[exp.DType, set[exp.DType]]] = _COERCES_TO

    # Coercion functions for binary operations.
    # Map of type pairs to a callable that takes both sides of the binary operation and returns the resulting type.
    BINARY_COERCIONS: t.ClassVar = {
        **swap_all(
            {
                (t, exp.DType.INTERVAL): lambda l, r: _coerce_date_literal(l, r.args.get("unit"))
                for t in exp.DataType.TEXT_TYPES
            }
        ),
        **swap_all(
            {
                # text + numeric will yield the numeric type to match most dialects' semantics
                (text, numeric): lambda l, r: (
                    l.type if l.type in exp.DataType.NUMERIC_TYPES else r.type
                )
                for text in exp.DataType.TEXT_TYPES
                for numeric in exp.DataType.NUMERIC_TYPES
            }
        ),
        **swap_all(
            {
                (exp.DType.DATE, exp.DType.INTERVAL): lambda l, r: _coerce_date(
                    l, r.args.get("unit")
                ),
            }
        ),
    }

    def __init__(
        self,
        schema: Schema,
        expression_metadata: ExprMetadataType | None = None,
        coerces_to: dict[exp.DType, set[exp.DType]] | None = None,
        binary_coercions: BinaryCoercions | None = None,
        overwrite_types: bool = True,
    ) -> None:
        self.schema = schema
        dialect = schema.dialect or Dialect()
        self.dialect = dialect
        self.expression_metadata = expression_metadata or dialect.EXPRESSION_METADATA
        self.coerces_to = coerces_to or dialect.COERCES_TO or self.COERCES_TO
        self.binary_coercions = binary_coercions or self.BINARY_COERCIONS

        # Keep annotated nodes alive so their ids cannot be reused while cached
        self._visited: dict[int, exp.Expr] = {}

        # Candidates for replacing NULL types with the dialect's default after inference.
        self._null_expressions: dict[int, exp.Expr] = {}

        # Databricks and Spark ≥v3 actually support NULL (i.e., VOID) as a type
        self._supports_null_type = dialect.SUPPORTS_NULL_TYPE

        # Keep ordered output columns until a parent set operation consumes them. Source
        # queries retain their results for subsequent column lookups.
        self._setop_column_types: dict[int, list[tuple[str, exp.DataType | exp.DType]]] = {}
        self._table_column_aliases: dict[int, tuple[exp.Table, dict[str, str]]] = {}

        # When set to False, this enables partial annotation by skipping already-annotated nodes
        self._overwrite_types = overwrite_types

        # Maps (Scope, source_name) to its column projections and types
        self._scope_source_selects: dict[
            tuple[Scope, str], dict[str, exp.DataType | exp.DType]
        ] = {}

    def clear(self) -> None:
        self._visited.clear()
        self._null_expressions.clear()
        self._setop_column_types.clear()
        self._table_column_aliases.clear()
        self._scope_source_selects.clear()

    # TODO (mypyc): should be expression: E -> E but mypyc resolves the TypeVar
    # to the isinstance-narrowed type, causing runtime type check failures.
    def _set_type(
        self, expression: exp.Expr, target_type: exp.DataType | exp.DType | None
    ) -> exp.Expr:
        prev_type = expression.type
        expression_id = id(expression)

        # TODO (mypyc): expression.type = ... should work but mypyc compiles the property
        # setter to enforce the getter's return type (Optional[DataType]), rejecting DType.
        # Bypass by converting and assigning to _type directly.
        dtype = target_type or exp.DType.UNKNOWN
        expression._type = dtype if isinstance(dtype, exp.DataType) else dtype.into_expr()
        self._visited[expression_id] = expression

        if (
            not self._supports_null_type
            and t.cast(exp.DataType, expression.type).this == exp.DType.NULL
        ):
            self._null_expressions[expression_id] = expression
        elif prev_type and t.cast(exp.DataType, prev_type).this == exp.DType.NULL:
            self._null_expressions.pop(expression_id, None)

        return expression

    def annotate(self, expression: E, annotate_scope: bool = True) -> E:
        # This flag is used to avoid costly scope traversals when we only care about annotating
        # non-column expressions (partial type inference), e.g., when simplifying in the optimizer
        if annotate_scope:
            for scope in traverse_scope(expression):
                self.annotate_scope(scope)

        # This takes care of non-traversable expressions
        self.annotate_expression(expression)

        # Replace NULL type with the default type of the targeted dialect, since the former is not an actual type;
        # it is mostly used to aid type coercion, e.g. in query set operations.
        # TODO (mypyc): uses list() + _set_type instead of direct expr.type = ... because
        # mypyc's property setter bypass rejects DType, and _set_type modifies the dict.
        for expr in list(self._null_expressions.values()):
            self._set_type(expr, self.dialect.DEFAULT_NULL_TYPE)

        return expression

    def _get_scope_source_selects(
        self, scope: Scope, source_name: str
    ) -> dict[str, exp.DataType | exp.DType]:
        key = (scope, source_name)
        selects = self._scope_source_selects.get(key)

        if selects is None:
            selects = {}
            source = scope.sources.get(source_name)

            pivots: list[exp.Pivot] = next(
                (
                    pivot.parent.args["pivots"]
                    for pivot in scope.pivots
                    if pivot.parent
                    and pivot.parent.args["pivots"][-1] is pivot
                    and pivot.alias_or_name == source_name
                ),
                [],
            )

            if pivots:
                parent = pivots[-1].parent
                parent_source = scope.sources.get(parent.alias_or_name) if parent else None

                if (
                    not isinstance(parent_source, Scope)
                    and isinstance(parent, exp.Table)
                    and not parent.db
                ):
                    # A chain aliased like the CTE it reads from shadows it in
                    # `scope.sources`, so reach for the CTE's scope directly
                    parent_source = scope.cte_sources.get(parent.name)

                if isinstance(parent_source, Scope):
                    src_types = self._get_source_scope_selects(parent_source)
                elif isinstance(parent, exp.Table) and isinstance(self.schema, MappingSchema):
                    src_types = (
                        self.schema.find(parent, raise_on_missing=False, ensure_data_types=True)
                        or {}
                    )
                else:
                    src_types = {}

                for pivot in pivots:
                    src_types = (
                        self._get_unpivot_column_types(pivot, src_types)
                        if pivot.unpivot
                        else self._get_pivot_column_types(pivot, src_types)
                    )

                selects = src_types

            elif isinstance(source, Scope):
                selects = self._get_source_scope_selects(source)

            self._scope_source_selects[key] = selects

        return selects

    def _get_source_scope_selects(self, source: Scope) -> dict[str, exp.DataType | exp.DType]:
        expression = source.expression

        if source.is_cte:
            # Recursive references can point to an unfinished UNION. Use its nearest resolved
            # anchor prefix until the recursive branches have been annotated.
            while (
                isinstance(expression, exp.SetOperation)
                and id(expression) not in self._setop_column_types
            ):
                expression = expression.this.unnest()

        if isinstance(expression, exp.UDTF):
            values = []

            if isinstance(expression, exp.Lateral):
                if isinstance(expression.this, exp.Explode):
                    values = [expression.this.this]
            elif isinstance(expression, exp.Unnest):
                values = [expression]
            elif not isinstance(expression, exp.TableFromRows):
                values = expression.expressions[0].expressions

            if not values:
                return {}

            alias_column_names = expression.alias_column_names

            if isinstance(expression, exp.Unnest):
                exp_type = expression.type
            elif isinstance(expression, exp.Lateral) and isinstance(expression.this, exp.Explode):
                exp_type = expression.this.type
            else:
                exp_type = None

            struct_type = exp_type if exp_type and exp_type.is_type(exp.DType.STRUCT) else None

            if struct_type:
                result = {
                    col_def.name: t.cast(t.Union[exp.DataType, exp.DType], col_def.kind)
                    for col_def in struct_type.expressions
                    if isinstance(col_def, exp.ColumnDef) and col_def.kind
                }
            elif isinstance(expression, exp.Values):
                # Like a set operation's, each VALUES column's type is coerced across all rows
                column_types: list[exp.DataType | exp.DType] = [exp.DType.NULL] * len(values)
                for row in expression.expressions:
                    for i, value in enumerate(row.expressions[: len(column_types)]):
                        column_types[i] = self._maybe_coerce(
                            value.type or exp.DType.UNKNOWN, column_types[i]
                        )

                result = dict(zip(alias_column_names, column_types))
            else:
                result = {alias: column.type for alias, column in zip(alias_column_names, values)}

            if isinstance(expression, exp.Unnest) and isinstance(
                offset := expression.args.get("offset"), exp.Identifier
            ):
                result[offset.name] = exp.DType.BIGINT

            return result

        if isinstance(expression, exp.SetOperation):
            return dict(self._get_setop_column_types(expression))

        if isinstance(expression, exp.Selectable):
            return {s.alias_or_name: s.type for s in expression.selects if s.type}

        return {}

    def annotate_scope(self, scope: Scope) -> None:
        # Iterate through all the expressions of the current scope in post-order, and annotate
        self.annotate_expression(scope.expression, scope)
        self._fixup_order_by_aliases(scope)

        if self.dialect.QUERY_RESULTS_ARE_STRUCTS and isinstance(scope.expression, exp.Query):
            scope.expression.meta.pop("query_type", None)
            column_types = (
                self._get_setop_column_types(scope.expression)
                if isinstance(scope.expression, exp.SetOperation)
                else ((select.output_name, select.type) for select in scope.expression.selects)
            )
            struct_type = exp.DataType(
                this=exp.DType.STRUCT,
                expressions=[
                    exp.ColumnDef(
                        this=exp.to_identifier(name),
                        kind=exp.DataType.build(kind) if kind else None,
                    )
                    for name, kind in column_types
                ],
                nested=True,
            )

            if struct_type.expressions and not any(
                not cd.kind or cd.kind.is_type(exp.DType.UNKNOWN) for cd in struct_type.expressions
            ):
                # We don't use `_set_type` on purpose here. If we annotated the query directly, then
                # using it in other contexts (e.g., ARRAY(<query>)) could result in incorrect type
                # annotations, i.e., it shouldn't be interpreted as a STRUCT value.
                scope.expression.meta["query_type"] = struct_type

    def annotate_expression(
        self,
        expression: exp.Expr,
        scope: Scope | None = None,
    ) -> None:
        """Annotate an expression and its descendants using the supplied scope."""
        stack = [(expression, False)]

        while stack:
            expr, children_annotated = stack.pop()

            if id(expr) in self._visited or (
                not self._overwrite_types and expr.type and not expr.is_type(exp.DType.UNKNOWN)
            ):
                continue  # We've already inferred the expression's type

            if not children_annotated:
                stack.append((expr, True))
                for child_expr in expr.iter_expressions():
                    stack.append((child_expr, False))
                continue

            if scope and isinstance(expr, exp.TableColumn):
                self._annotate_table_column(expr, scope)
                continue

            if scope and isinstance(expr, exp.Column) and expr.table and not expr.is_star:
                source = None
                source_scope: Scope | None = scope
                while source_scope and not source:
                    source = source_scope.sources.get(expr.table)
                    if not source:
                        source_scope = source_scope.parent

                if isinstance(source, exp.Table):
                    source_id = id(source)
                    if source_id not in self._table_column_aliases:
                        column_aliases: dict[str, str] = {}
                        if alias_columns := source.alias_column_names:
                            for alias, name in zip(alias_columns, self.schema.column_names(source)):
                                column_aliases.setdefault(alias, name)
                        self._table_column_aliases[source_id] = (source, column_aliases)

                    physical_name = self._table_column_aliases[source_id][1].get(expr.name)
                    column_expr = (
                        exp.column(physical_name, quoted=True)
                        if physical_name is not None
                        else expr
                    )

                    table_col_type: exp.DataType | exp.DType | None = self.schema.get_column_type(
                        source, column_expr
                    )
                    if (
                        isinstance(table_col_type, exp.DataType)
                        and table_col_type.is_type(exp.DType.UNKNOWN)
                        and source.args.get("pivots")
                    ):
                        table_col_type = (
                            self._get_scope_source_selects(source_scope or scope, expr.table).get(
                                expr.name
                            )
                            or exp.DType.UNKNOWN
                        )

                    self._set_type(expr, table_col_type)
                elif source and source_scope:
                    col_type = self._get_scope_source_selects(source_scope, expr.table).get(
                        expr.name
                    )
                    if col_type:
                        self._set_type(expr, col_type)
                    elif isinstance(source.expression, exp.Unnest):
                        self._set_type(expr, source.expression.type)
                    else:
                        self._set_type(expr, exp.DType.UNKNOWN)
                elif (
                    not source
                    and scope.pivots
                    and (
                        col_type := self._get_scope_source_selects(scope, expr.table).get(expr.name)
                    )
                ):
                    self._set_type(expr, col_type)
                else:
                    self._set_type(expr, exp.DType.UNKNOWN)

                self._restore_dot_parts(expr)

                if expr.type and expr.type.args.get("nullable") is False:
                    expr.meta["nonnull"] = True
                continue

            if isinstance(expr, exp.SetOperation):
                self._annotate_set_operation(expr)

            spec = self.expression_metadata.get(expr.__class__)

            if spec and (annotator := spec.get("annotator")):
                annotator(self, expr)
            elif spec and (returns := spec.get("returns")):
                self._set_type(expr, returns)
            else:
                self._set_type(expr, exp.DType.UNKNOWN)

            self._restore_dot_parts(expr)

    def _annotate_table_column(self, expression: exp.TableColumn, scope: Scope) -> None:
        source = scope.sources.get(expression.name)
        column_types = None
        if any(pivot.alias == expression.name for pivot in scope.pivots):
            column_types = self._get_scope_source_selects(scope, expression.name)
        elif isinstance(source, Scope):
            if (query_type := source.expression.meta_get("query_type")) and query_type.is_type(
                exp.DType.STRUCT
            ):
                self._set_type(expression, query_type)
                return
        elif isinstance(source, exp.Table) and isinstance(self.schema, MappingSchema):
            column_types = self.schema.find(source, raise_on_missing=False, ensure_data_types=True)

        if (
            isinstance(column_types, dict)
            and column_types
            and all(
                kind is not None
                and not exp.DataType.build(kind, copy=False).is_type(exp.DType.UNKNOWN)
                for kind in column_types.values()
            )
        ):
            self._set_type(
                expression,
                exp.DataType(
                    this=exp.DType.STRUCT,
                    expressions=[
                        exp.ColumnDef(
                            this=exp.to_identifier(str(name)), kind=exp.DataType.build(kind)
                        )
                        for name, kind in column_types.items()
                    ],
                    nested=True,
                ),
            )
        else:
            self._set_type(expression, exp.DType.UNKNOWN)

    def _restore_dot_parts(self, expr: exp.Expr) -> None:
        # Dot access into semi-structured values is a case sensitive data lookup, i.e. the
        # engine doesn't resolve the keys as identifiers, so we undo their normalization.
        dot_parts = expr.meta_get("dot_parts")
        if not dot_parts or not expr.is_type(exp.DType.JSON, exp.DType.MAP, exp.DType.VARIANT):
            if dot_parts:
                # A struct field can itself contain semi-structured data. Resolve each
                # struct access before deciding whether the remaining keys are identifiers.
                if expr.is_type(exp.DType.STRUCT) and isinstance(expr.parent, exp.Dot):
                    expr.parent.meta["dot_parts"] = dot_parts[1:]
                if expr.type is None or expr.is_type(exp.DType.UNKNOWN):
                    return
                expr.meta.pop("dot_parts", None)
            return

        parent = expr.parent
        for part in dot_parts:
            if not isinstance(parent, exp.Dot):
                break

            identifier = parent.expression
            if isinstance(identifier, exp.Identifier):
                # Rename in place to preserve the identifier's meta, e.g. token positions
                identifier.set("this", part)
                identifier.set("quoted", True)
            else:
                identifier.replace(exp.to_identifier(part, quoted=True))

            parent = parent.parent

        expr.meta.pop("dot_parts", None)

    def _fixup_order_by_aliases(self, scope: Scope) -> None:
        query = scope.expression
        if not isinstance(query, exp.Query):
            return

        order = query.args.get("order")
        if not order:
            return

        # Build alias -> type map from fully-annotated projections (last match wins,
        # consistent with how _expand_alias_refs handles duplicate aliases).
        alias_types: dict[str, exp.DataType | exp.DType] = {}
        for sel in query.selects:
            if (
                isinstance(sel, exp.Alias)
                and sel.this.type
                and not sel.this.is_type(exp.DType.UNKNOWN)
            ):
                alias_types[sel.alias] = sel.this.type

        if not alias_types:
            return

        for ordered in order.expressions:
            alias_cols = [
                c for c in ordered.find_all(exp.Column) if not c.table and c.name in alias_types
            ]
            for col in alias_cols:
                self._set_type(col, alias_types[col.name])

            if alias_cols:
                for node in ordered.walk(prune=lambda n: isinstance(n, exp.Subquery)):
                    if not isinstance(node, (exp.Column, exp.Literal)):
                        self._visited.pop(id(node), None)
                self.annotate_expression(ordered, scope)

    def _maybe_coerce(
        self,
        type1: exp.DataType | exp.DType,
        type2: exp.DataType | exp.DType,
    ) -> exp.DataType | exp.DType:
        """
        Returns type2 if type1 can be coerced into it, otherwise type1.

        If either type is parameterized (e.g. DECIMAL(18, 2) contains two parameters),
        we assume type1 does not coerce into type2, so we also return it in this case.
        """
        if isinstance(type1, exp.DataType):
            if type1.expressions or not isinstance(type1.this, exp.DType):
                return type1
            type1_value = type1.this
        else:
            type1_value = type1

        if isinstance(type2, exp.DataType):
            if type2.expressions or not isinstance(type2.this, exp.DType):
                return type2
            type2_value = type2.this
        else:
            type2_value = type2

        # We propagate the UNKNOWN type upwards if found
        if exp.DType.UNKNOWN in (type1_value, type2_value):
            return exp.DType.UNKNOWN

        if type1_value == exp.DType.NULL:
            return type2_value
        if type2_value == exp.DType.NULL:
            return type1_value

        return type2_value if type2_value in self.coerces_to.get(type1_value, {}) else type1_value

    def _get_setop_column_types(
        self, expression: exp.SetOperation
    ) -> list[tuple[str, exp.DataType | exp.DType]]:
        return self._setop_column_types.get(id(expression), [])

    def _annotate_set_operation(self, expression: exp.SetOperation) -> None:
        # The expression annotation pass visits children first, including when a scope is
        # annotated independently. Preserve duplicate names until positional matching is done.
        operands: list[list[tuple[str, exp.DataType | exp.DType]]] = []
        for operand in (expression.this.unnest(), expression.expression.unnest()):
            if isinstance(operand, exp.SetOperation):
                operands.append(self._setop_column_types.pop(id(operand), []))
            else:
                operands.append(
                    [(s.alias_or_name, s.type or exp.DType.UNKNOWN) for s in operand.selects]
                )
        left, right = operands

        columns: list[tuple[str, exp.DataType | exp.DType]] = []
        if left and right:
            if expression.args.get("by_name"):
                left_types = dict(left)
                right_types = dict(right)
                if on := expression.args.get("on"):
                    names = [column.name for column in on]
                elif expression.kind == "INNER":
                    names = [name for name in left_types if name in right_types]
                elif expression.side == "LEFT":
                    names = list(left_types)
                else:
                    names = list({**left_types, **right_types})

                # Missing columns are NULL-filled, preserving the other operand's type.
                columns = [
                    (
                        name,
                        self._maybe_coerce(
                            left_types.get(name, exp.DType.NULL),
                            right_types.get(name, exp.DType.NULL),
                        ),
                    )
                    for name in names
                ]
            elif len(left) == len(right):
                columns = [
                    (name, self._maybe_coerce(left_type, right_type))
                    for (name, left_type), (_, right_type) in zip(left, right)
                ]

        self._setop_column_types[id(expression)] = columns

    def _get_unpivot_column_types(
        self, pivot: exp.Pivot, src_types: dict[str, exp.DataType | exp.DType]
    ) -> dict[str, exp.DataType | exp.DType]:
        new_types: dict[str, exp.DataType | exp.DType] = {}

        for field in pivot.fields:
            field_col = field.this
            first = seq_get(field.expressions, 0)

            if isinstance(first, exp.PivotAlias) and (alias_node := first.args.get("alias")):
                new_types[field_col.name] = alias_node.type
                in_src = first.this
            else:
                new_types[field_col.name] = exp.DType.VARCHAR.into_expr()
                in_src = first

            in_cols = in_src.expressions if isinstance(in_src, exp.Tuple) else [in_src]
            val_expr = seq_get(pivot.expressions, 0)
            val_cols = val_expr.expressions if isinstance(val_expr, exp.Tuple) else [val_expr]
            for val_col, in_col in zip(val_cols, in_cols):
                # A chained operator's IN-list may name columns an earlier operator
                # produced, which carry no annotation of their own
                in_type = in_col.type
                if not in_type or in_type.is_type(exp.DType.UNKNOWN):
                    in_type = src_types.get(in_col.output_name) or in_type
                new_types[val_col.output_name] = in_type

        return {
            name: type_
            for name in pivot.output_columns(src_types)
            if (type_ := new_types.get(name) or src_types.get(name))
        }

    def _get_pivot_column_types(
        self, pivot: exp.Pivot, src_types: dict[str, exp.DataType | exp.DType]
    ) -> dict[str, exp.DataType | exp.DType]:
        first_field = seq_get(pivot.fields, 0)
        if not isinstance(first_field, exp.In):
            raise OptimizeError(f"Expected In expression for pivot field, got {type(first_field)}")

        if pivot.args.get("columns") == []:
            excluded = {column.name for column in pivot.find_all(exp.Column)}
            passthrough = [name for name in src_types if name not in excluded]
            aliases = pivot.alias_column_names
            return {
                seq_get(aliases, i) or name: src_types[name] for i, name in enumerate(passthrough)
            }

        pivot_constants = first_field.expressions

        # The first agg_cols_offset entries are source columns that pass through the PIVOT unchanged;
        # the rest are the aggregated columns, one per combination of IN value and aggregate function.
        output_to_src = pivot.output_columns(src_types)

        # Output types may be requested before the PIVOT itself has been annotated.
        agg_types: list[exp.DataType | None] = []
        for agg in pivot.expressions:
            if not agg.type or agg.is_type(exp.DType.UNKNOWN):
                agg = agg.copy()
                for column in agg.find_all(exp.Column):
                    self._set_type(column, src_types.get(column.name))
                self.annotate_expression(agg)
            agg_types.append(agg.this.type if isinstance(agg, exp.Alias) else agg.type)
        agg_cols_offset = len(output_to_src) - len(pivot_constants) * len(agg_types)
        if agg_cols_offset < 0:
            raise OptimizeError(f"Negative pivot column offset: {agg_cols_offset}")

        output_names = list(output_to_src)
        new_types: dict[str, exp.DataType | exp.DType] = {}

        for name in output_names[:agg_cols_offset]:
            if type_ := src_types.get(output_to_src[name]):
                new_types[name] = type_

        for name, agg_type in zip(
            output_names[agg_cols_offset:],
            (a for _ in pivot_constants for a in agg_types),
        ):
            if agg_type:
                new_types[name] = agg_type

        return new_types

    def _annotate_binary(self, expression: B) -> B:
        left, right = expression.left, expression.right
        if not left or not right:
            expression_sql = expression.sql(self.dialect)
            logger.warning(f"Failed to annotate badly formed binary expression: {expression_sql}")
            self._set_type(expression, None)
            return expression

        left_type = left.type.this if left.type else exp.DType.UNKNOWN
        right_type = right.type.this if right.type else exp.DType.UNKNOWN

        # TODO (mypyc): should be isinstance(expression, (exp.Connector, exp.Predicate)) but
        # mypyc narrows the variable to the first type in a tuple/or isinstance check when
        # the types are sibling @trait classes, rejecting instances of the second type.
        if issubclass(type(expression), (exp.Connector, exp.Predicate)):
            self._set_type(expression, exp.DType.BOOLEAN)
        elif (left_type, right_type) in self.binary_coercions:
            self._set_type(expression, self.binary_coercions[(left_type, right_type)](left, right))
        else:
            self._annotate_by_args(expression, left, right)

        if isinstance(expression, exp.Is) or (
            left.meta_get("nonnull") is True and right.meta_get("nonnull") is True
        ):
            expression.meta["nonnull"] = True

        return expression

    def _annotate_unary(self, expression: E) -> E:
        if isinstance(expression, exp.Not):
            self._set_type(expression, exp.DType.BOOLEAN)
        else:
            self._set_type(expression, expression.this.type)

        if expression.this.meta_get("nonnull") is True:
            expression.meta["nonnull"] = True

        return expression

    def _annotate_literal(self, expression: exp.Literal) -> exp.Literal:
        if expression.is_string:
            self._set_type(expression, exp.DType.VARCHAR)
        elif expression.is_int:
            self._set_type(expression, exp.DType.INT)
        else:
            self._set_type(expression, exp.DType.DOUBLE)

        expression.meta["nonnull"] = True

        return expression

    def _annotate_by_args(
        self,
        expression: E,
        *args: str | exp.Expr,
        promote: bool = False,
        array: bool = False,
    ) -> E:
        literal_type = None
        non_literal_type = None
        nested_type = None

        for arg in args:
            if isinstance(arg, str):
                expressions = expression.args.get(arg)
            else:
                expressions = arg

            for expr in ensure_list(expressions):
                expr_type = expr.type

                if expr_type is None or expr_type.is_type(exp.DType.UNKNOWN):
                    self._set_type(expression, exp.DType.UNKNOWN)
                    return expression

                if nested_type:
                    # Only resolve ARRAY<NULL>; preserve existing coercion for other nested types.
                    if (
                        nested_type.is_type(exp.DType.ARRAY)
                        and nested_type.expressions
                        and nested_type.expressions[0].is_type(exp.DType.NULL)
                        and expr_type.is_type(exp.DType.ARRAY)
                        and expr_type.expressions
                    ):
                        nested_type = expr_type
                    continue

                # Prefer the first nested data type, resolving ARRAY<NULL> from later arrays.
                if expr_type.args.get("nested"):
                    nested_type = expr_type
                elif isinstance(expr, exp.Literal):
                    literal_type = self._maybe_coerce(literal_type or expr_type, expr_type)
                else:
                    non_literal_type = self._maybe_coerce(non_literal_type or expr_type, expr_type)

        result_type = None

        if nested_type:
            result_type = nested_type
        elif literal_type and non_literal_type:
            if self.dialect.PRIORITIZE_NON_LITERAL_TYPES:
                literal_this_type = (
                    literal_type.this if isinstance(literal_type, exp.DataType) else literal_type
                )
                non_literal_this_type = (
                    non_literal_type.this
                    if isinstance(non_literal_type, exp.DataType)
                    else non_literal_type
                )
                if (
                    literal_this_type in exp.DataType.INTEGER_TYPES
                    and non_literal_this_type in exp.DataType.INTEGER_TYPES
                ) or (
                    literal_this_type in exp.DataType.REAL_TYPES
                    and non_literal_this_type in exp.DataType.REAL_TYPES
                ):
                    result_type = non_literal_type

            if result_type is None:
                result_type = self._maybe_coerce(non_literal_type, literal_type)
        else:
            result_type = (
                literal_type or non_literal_type or (exp.DType.NULL if array else exp.DType.UNKNOWN)
            )

        self._set_type(expression, result_type)

        if promote:
            this_type = result_type.this if isinstance(result_type, exp.DataType) else result_type
            if this_type in exp.DataType.INTEGER_TYPES:
                self._set_type(expression, exp.DType.BIGINT)
            elif this_type in exp.DataType.FLOAT_TYPES:
                self._set_type(expression, exp.DType.DOUBLE)

        if array and not expression.is_type(exp.DType.UNKNOWN):
            self._set_type(
                expression,
                exp.DataType(this=exp.DType.ARRAY, expressions=[expression.type], nested=True),
            )

        return expression

    def _annotate_timeunit(
        self, expression: exp.TimeUnit | exp.DateTrunc
    ) -> exp.TimeUnit | exp.DateTrunc:
        datatype: exp.DataType | exp.DType
        if expression.this.type.this in exp.DataType.TEXT_TYPES:
            datatype = _coerce_date_literal(expression.this, expression.unit)
        elif expression.this.type.this in exp.DataType.TEMPORAL_TYPES:
            datatype = _coerce_date(expression.this, expression.unit)
        else:
            datatype = exp.DType.UNKNOWN

        self._set_type(expression, datatype)
        return expression

    def _annotate_bracket(self, expression: exp.Bracket) -> exp.Bracket:
        bracket_arg = expression.expressions[0]
        this = expression.this

        if isinstance(bracket_arg, exp.Slice):
            self._set_type(expression, this.type)
        elif this.type.is_type(exp.DType.ARRAY):
            self._set_type(expression, seq_get(this.type.expressions, 0))
        elif isinstance(this, (exp.Map, exp.VarMap)) and bracket_arg in this.keys:
            index = this.keys.index(bracket_arg)
            value = seq_get(this.values, index)
            self._set_type(expression, value.type if value else None)
        else:
            self._set_type(expression, exp.DType.UNKNOWN)

        return expression

    def _annotate_div(self, expression: exp.Div) -> exp.Div:
        left, right = expression.left, expression.right
        left_type = left.type.this if left.type else exp.DType.UNKNOWN
        right_type = right.type.this if right.type else exp.DType.UNKNOWN

        if (
            expression.args.get("typed")
            and left_type in exp.DataType.INTEGER_TYPES
            and right_type in exp.DataType.INTEGER_TYPES
        ):
            self._set_type(expression, exp.DType.BIGINT)
        else:
            self._set_type(expression, self._maybe_coerce(left_type, right_type))
            if expression.type and expression.type.this not in exp.DataType.REAL_TYPES:
                self._set_type(expression, self._maybe_coerce(expression.type, exp.DType.DOUBLE))

        return expression

    def _annotate_dot(self, expression: exp.Dot) -> exp.Dot:
        self._set_type(expression, None)

        # Propagate type from qualified UDF calls (e.g., db.my_udf(...))
        if isinstance(expression.expression, exp.Anonymous):
            self._set_type(expression, expression.expression.type)
            return expression

        this_type = expression.this.type

        if this_type and this_type.is_type(exp.DType.STRUCT):
            for e in this_type.expressions:
                if e.name == expression.expression.name:
                    self._set_type(expression, e.kind)
                    break

        return expression

    def _annotate_explode(self, expression: exp.Explode) -> exp.Explode:
        input_type = expression.this.type
        if input_type and input_type.is_type(exp.DType.ARRAY):
            self._set_type(expression, seq_get(input_type.expressions, 0))
        else:
            self._set_type(expression, None)
        return expression

    def _annotate_unnest(self, expression: exp.Unnest) -> exp.Unnest:
        child = seq_get(expression.expressions, 0)

        if child and child.is_type(exp.DType.ARRAY):
            expr_type = seq_get(child.type.expressions, 0)
        else:
            expr_type = None

        self._set_type(expression, expr_type)
        return expression

    def _annotate_subquery(self, expression: exp.Subquery) -> exp.Subquery:
        # For scalar subqueries (subqueries with a single projection), infer the type
        # from that single projection. This allows type propagation in cases like:
        # SELECT (SELECT 1 AS c) AS c
        query = expression.unnest()

        if isinstance(query, exp.Query):
            if query.args.get("kind") == "STRUCT":
                self._set_type(expression, query.meta_get("query_type"))
                return expression
            selects = query.selects
            if len(selects) == 1:
                self._set_type(expression, selects[0].type)
                return expression

        self._set_type(expression, exp.DType.UNKNOWN)
        return expression

    def _annotate_struct_value(self, expression: exp.Expr) -> exp.DataType | None | exp.ColumnDef:
        # Case: STRUCT(key AS value)
        this: exp.Expr | None = None
        kind = expression.type

        if alias := expression.args.get("alias"):
            this = alias.copy()
        elif expression.expression:
            # Case: STRUCT(key = value) or STRUCT(key := value)
            this = expression.this.copy()
            kind = expression.expression.type
        elif isinstance(expression, exp.Column):
            # Case: STRUCT(c)
            this = expression.this.copy()

        if kind and kind.is_type(exp.DType.UNKNOWN):
            return None

        if this:
            return exp.ColumnDef(this=this, kind=kind)

        return kind

    def _annotate_struct(self, expression: exp.Struct) -> exp.Struct:
        expressions = []
        for expr in expression.expressions:
            struct_field_type = self._annotate_struct_value(expr)
            if struct_field_type is None:
                self._set_type(expression, None)
                return expression

            expressions.append(struct_field_type)

        self._set_type(
            expression,
            exp.DataType(this=exp.DType.STRUCT, expressions=expressions, nested=True),
        )
        return expression

    @t.overload
    def _annotate_map(self, expression: exp.Map) -> exp.Map: ...

    @t.overload
    def _annotate_map(self, expression: exp.VarMap) -> exp.VarMap: ...

    def _annotate_map(self, expression):
        keys = expression.args.get("keys")
        values = expression.args.get("values")

        map_type = exp.DataType(this=exp.DType.MAP)
        if isinstance(keys, exp.Array) and isinstance(values, exp.Array):
            key_type = seq_get(keys.type.expressions, 0)
            value_type = seq_get(values.type.expressions, 0)

            if (
                not key_type
                or key_type.is_type(exp.DType.UNKNOWN)
                or not value_type
                or value_type.is_type(exp.DType.UNKNOWN)
            ):
                self._set_type(expression, exp.DType.UNKNOWN)
                return expression

            map_type.set("expressions", [key_type, value_type])
            map_type.set("nested", True)

        self._set_type(expression, map_type)
        return expression

    def _annotate_to_map(self, expression: exp.ToMap) -> exp.ToMap:
        map_type = exp.DataType(this=exp.DType.MAP)
        arg = expression.this
        if arg.is_type(exp.DType.STRUCT):
            for coldef in arg.type.expressions:
                kind = coldef.kind
                if kind != exp.DType.UNKNOWN:
                    map_type.set("expressions", [exp.DType.VARCHAR.into_expr(), kind])
                    map_type.set("nested", True)
                    break

        self._set_type(expression, map_type)
        return expression

    def _annotate_extract(self, expression: exp.Extract) -> exp.Extract:
        part = expression.name
        if part == "TIME":
            self._set_type(expression, exp.DType.TIME)
        elif part == "DATE":
            self._set_type(expression, exp.DType.DATE)
        elif part == "DATETIME":
            self._set_type(expression, exp.DType.DATETIME)
        elif part in BIGINT_EXTRACT_DATE_PARTS:
            self._set_type(expression, exp.DType.BIGINT)
        else:
            self._set_type(expression, exp.DType.INT)
        return expression

    def _annotate_within_group(self, expression: exp.WithinGroup) -> exp.WithinGroup:
        if isinstance(expression.this, exp.PercentileDisc):
            order = expression.args.get("expression")
            order_expressions = order and order.expressions
            sort_type = order_expressions[0].this.type if order_expressions else exp.DType.UNKNOWN
            self._set_type(expression, sort_type)
            return expression

        return self._annotate_by_args(expression, "this")

    def _annotate_by_array_element(self, expression: exp.Expr) -> exp.Expr:
        array_arg = expression.this
        if array_arg.type.is_type(exp.DType.ARRAY):
            element_type = seq_get(array_arg.type.expressions, 0) or exp.DType.UNKNOWN
            self._set_type(expression, element_type)
        else:
            self._set_type(expression, exp.DType.UNKNOWN)

        return expression

