from __future__ import annotations

import typing as t

from sqlglot import exp
from sqlglot.dialects.dialect import Dialect, DialectType
from sqlglot.helper import name_sequence, seq_get, ensure_list
from sqlglot.optimizer.normalize_identifiers import normalize_identifiers
from sqlglot.optimizer.scope import Scope, traverse_scope

if t.TYPE_CHECKING:
    from sqlglot._typing import E
    from collections.abc import Sequence


def qualify_tables(
    expression: E,
    db: str | exp.Identifier | None = None,
    catalog: str | exp.Identifier | None = None,
    on_qualify: t.Callable[[exp.Table], None] | None = None,
    dialect: DialectType = None,
    canonicalize_table_aliases: bool = False,
) -> E:
    """
    Rewrite sqlglot AST to have fully qualified tables. Join constructs such as
    (t1 JOIN t2) AS t will be expanded into (SELECT * FROM t1 AS t1 CROSS JOIN t2 AS t2) AS t.

    Examples:
        >>> import sqlglot
        >>> expression = sqlglot.parse_one("SELECT 1 FROM tbl")
        >>> qualify_tables(expression, db="db").sql()
        'SELECT 1 FROM db.tbl AS tbl'
        >>>
        >>> expression = sqlglot.parse_one("SELECT 1 FROM (t1 JOIN t2) AS t")
        >>> qualify_tables(expression).sql()
        'SELECT 1 FROM (SELECT * FROM t1 AS t1 CROSS JOIN t2 AS t2) AS t'

    Args:
        expression: Expr to qualify
        db: Database name
        catalog: Catalog name
        on_qualify: Callback after a table has been qualified.
        dialect: The dialect to parse catalog and schema into.
        canonicalize_table_aliases: Whether to use canonical aliases (_0, _1, ...) for all sources
            instead of preserving table names. Defaults to False.

    Returns:
        The qualified expression.
    """
    dialect = Dialect.get_or_raise(dialect)
    next_alias_name = name_sequence("_")

    if db := db or None:
        db = exp.parse_identifier(db, dialect=dialect)
        db.meta["is_table"] = True
        db = normalize_identifiers(db, dialect=dialect)
    if catalog := catalog or None:
        catalog = exp.parse_identifier(catalog, dialect=dialect)
        catalog.meta["is_table"] = True
        catalog = normalize_identifiers(catalog, dialect=dialect)

    def _qualify(table: exp.Table) -> None:
        if isinstance(table.this, exp.Identifier):
            if db and not table.args.get("db"):
                table.set("db", db.copy())
            if catalog and not table.args.get("catalog") and table.args.get("db"):
                table.set("catalog", catalog.copy())

    if (db or catalog) and not isinstance(expression, exp.Query):
        with_ = expression.args.get("with_") or exp.With()
        cte_names = {cte.alias_or_name for cte in with_.expressions}

        for node in expression.walk(prune=lambda n: isinstance(n, exp.Query)):
            if isinstance(node, exp.Table) and node.name not in cte_names:
                _qualify(node)

    def _set_alias(
        expression: exp.Expr,
        canonical_aliases: dict[str, str],
        target_alias: str | None = None,
        scope: Scope | None = None,
        normalize: bool = False,
        columns: Sequence[str | exp.Identifier | exp.ColumnDef] | None = None,
    ) -> None:
        alias = expression.args.get("alias") or exp.TableAlias()

        if canonicalize_table_aliases:
            new_alias_name = next_alias_name()
            canonical_aliases[alias.name or target_alias or ""] = new_alias_name
        elif not alias.name:
            new_alias_name = target_alias or next_alias_name()
            if normalize and target_alias:
                new_alias_name = normalize_identifiers(new_alias_name, dialect=dialect).name
        else:
            return

        alias.set("this", exp.to_identifier(new_alias_name))

        if columns:
            alias.set(
                "columns",
                [exp.to_identifier(c) if isinstance(c, str) else c.copy() for c in columns],
            )

        expression.set("alias", alias)

        if scope:
            scope.rename_source(None, new_alias_name)

    # Expanding join constructs exposes new sources, including nested join constructs that only
    # become derived tables afterwards, so the scopes are rebuilt until nothing else is expanded
    # (a list is used so that every construct in a pass expands before the rebuild)
    scopes = traverse_scope(expression)
    while any([_expand_join_construct(d) for scope in scopes for d in scope.derived_tables]):
        scopes = traverse_scope(expression)

    for scope in scopes:
        parent = scope.parent
        local_columns = scope.local_columns
        canonical_aliases: dict[str, str] = {}

        queries: list[exp.Expr] = list(scope.subqueries)

        # Subquery wrappers around a DML / DDL query fragment, e.g., a CREATE FUNCTION body or
        # an UPDATE's SET subquery, don't belong to any scope, so they aren't collected above
        if scope.is_root and isinstance(scope.expression, exp.Subquery):
            queries.append(scope.expression.unnest())
        elif scope.is_subquery:
            queries.append(scope.expression)

        for query in queries:
            subquery = query.parent
            if isinstance(subquery, exp.Subquery):
                unwrapped = subquery.unwrap()
                if isinstance(unwrapped.parent, (exp.From, exp.Join)):
                    # We can reach this from a wrapped derived table, which must keep its alias
                    continue

                if isinstance(unwrapped.parent, exp.Create) and unwrapped is not subquery:
                    # Function bodies may require wrapping parentheses, e.g. in BigQuery
                    # `... AS ((SELECT 1))` the outer parens delimit the body itself
                    unwrapped.set("this", subquery)
                else:
                    unwrapped.replace(subquery)

        for derived_table in scope.derived_tables:
            _set_alias(derived_table, canonical_aliases, scope=scope)
            if pivot := seq_get(derived_table.args.get("pivots") or [], -1):
                _set_alias(pivot, canonical_aliases)

        table_aliases = {}

        for name, source in scope.sources.items():
            # A source can appear in many scopes, e.g. as a lateral source of a UDTF scope or as a CTE
            # propagated to inner scopes. Deferring to the parent scope when it contains the same source
            # ensures each source is processed once, in the outermost scope that contains it
            if parent and parent.sources.get(name) is source:
                continue

            if isinstance(source, exp.Table):
                # When the name is empty, it means that we have a non-table source, e.g. a pivoted cte
                is_real_table_source = bool(name)

                if pivot := seq_get(source.args.get("pivots") or [], -1):
                    name = source.name

                table_this = source.this
                table_alias = source.args.get("alias")
                function_columns: Sequence[str | exp.Identifier | exp.ColumnDef] | None = None
                if isinstance(table_this, exp.Func):
                    if not table_alias:
                        function_columns = ensure_list(
                            dialect.DEFAULT_FUNCTIONS_COLUMN_NAMES.get(type(table_this))
                        )
                    elif columns := table_alias.columns:
                        function_columns = columns
                    elif type(table_this) in dialect.DEFAULT_FUNCTIONS_COLUMN_NAMES:
                        function_columns = ensure_list(source.alias_or_name)
                        source.set("alias", None)
                        name = ""

                _set_alias(
                    source,
                    canonical_aliases,
                    target_alias=name or source.name or None,
                    normalize=True,
                    columns=function_columns,
                )

                source_fqn = ".".join(p.name for p in source.parts)
                had_explicit_alias = table_alias and table_alias.name
                if not had_explicit_alias or source_fqn not in table_aliases:
                    table_aliases[source_fqn] = source.args["alias"].this.copy()

                if pivot:
                    target_alias = source.alias if pivot.unpivot else None
                    _set_alias(pivot, canonical_aliases, target_alias=target_alias, normalize=True)

                    # This case corresponds to a pivoted CTE, we don't want to qualify that
                    if isinstance(scope.sources.get(source.alias_or_name), Scope):
                        continue

                if is_real_table_source:
                    _qualify(source)

                    if on_qualify:
                        on_qualify(source)
            elif isinstance(source, Scope) and source.is_udtf:
                _set_alias(udtf := source.expression, canonical_aliases)

                table_alias = udtf.args["alias"]

                if isinstance(udtf, exp.Values) and not table_alias.columns:
                    column_aliases = [
                        normalize_identifiers(i, dialect=dialect)
                        for i in dialect.generate_values_aliases(udtf)
                    ]
                    table_alias.set("columns", column_aliases)
                elif (
                    isinstance(udtf, exp.TableFromRows)
                    or (isinstance(udtf, exp.Lateral) and isinstance(udtf.this, exp.UDTF))
                ) and not table_alias.columns:
                    default_columns = dialect.DEFAULT_FUNCTIONS_COLUMN_NAMES.get(type(udtf.this))
                    if default_columns:
                        table_alias.set(
                            "columns",
                            [
                                normalize_identifiers(exp.to_identifier(c), dialect=dialect)
                                for c in ensure_list(default_columns)
                            ],
                        )

        for table in scope.tables:
            if not table.alias and isinstance(table.parent, (exp.From, exp.Join)):
                _set_alias(table, canonical_aliases, target_alias=table.name)

        for column in local_columns:
            column_table = column.table

            if column.db:
                table_alias = table_aliases.get(".".join(p.name for p in column.parts[0:-1]))

                if table_alias:
                    for p in exp.COLUMN_PARTS[1:]:
                        column.set(p, None)

                    column.set("table", table_alias.copy())
            elif (
                canonical_aliases
                and column_table
                and (canonical_table := canonical_aliases.get(column_table))
                and canonical_table != column_table
            ):
                # Amend existing aliases, e.g. t.c -> _0.c if t is aliased to _0
                column.set("table", exp.to_identifier(canonical_table))

    return expression


def _expand_join_construct(derived_table: exp.Subquery) -> bool:
    # Expands e.g. ((a JOIN b) JOIN c) AS j into a SELECT *, collecting the joins of every
    # unaliased wrapper
    source = derived_table.this
    joins: list[exp.Expr] = []
    while isinstance(source, (exp.Subquery, exp.Table)):
        joins[:0] = source.args.get("joins") or []
        if (
            isinstance(source, exp.Table)
            or source.alias
            or not isinstance(source.this, (exp.Subquery, exp.Table))
        ):
            break
        source = source.this

    if isinstance(source, exp.Table) or joins:
        source.set("joins", None)
        derived_table.this.replace(exp.select("*").from_(source.copy(), copy=False))
        derived_table.this.set("joins", joins or None)
        return True

    return False

