    def _parse_conjunction(self) -> exp.Expr | None:
        this = super()._parse_conjunction()
        while self._match(TokenType.XOR):
            comments = self._prev_comments
            this = self.expression(
                exp.Xor(this=this, expression=super()._parse_conjunction()),
                comments=comments,
            )
        return this

    def _parse_not(self) -> exp.Expr:
        if self._prev.text == "!":
            # ! binds more tightly than NOT, so preserve its grouping when generating NOT.
            return self.expression(
                exp.Paren(this=self.expression(exp.Not(this=self._parse_unary())))
            )
        return self.expression(exp.Not(this=self._parse_equality()))

    def _parse_bitwise(self) -> exp.Expr | None:
        this = self._parse_bitwise_and()
        while self._match(TokenType.PIPE):
            comments = self._prev_comments
            this = self.expression(
                exp.BitwiseOr(this=this, expression=self._parse_bitwise_and()),
                comments=comments,
            )
        return this

    def _parse_bitwise_and(self) -> exp.Expr | None:
        this = self._parse_bitwise_shift()
        while self._match(TokenType.AMP):
            comments = self._prev_comments
            this = self.expression(
                exp.BitwiseAnd(this=this, expression=self._parse_bitwise_shift()),
                comments=comments,
            )
        return this

    def _parse_bitwise_shift(self) -> exp.Expr | None:
        this = self._parse_term()
        while True:
            if self._match_pair(TokenType.LT, TokenType.LT):
                klass: type[exp.BitwiseLeftShift | exp.BitwiseRightShift] = exp.BitwiseLeftShift
            elif self._match_pair(TokenType.GT, TokenType.GT):
                klass = exp.BitwiseRightShift
            else:
                break

            comments = self._prev_comments
            this = self.expression(
                klass(this=this, expression=self._parse_term()), comments=comments
            )
        return this

    def _parse_column_constraint(self) -> exp.Expr | None:
        # SIGNED is the default for numeric types, so MySQL ignores it
        self._match_text_seq("SIGNED")
        if self._match(TokenType.KEY):
            return self.expression(exp.ColumnConstraint(kind=self._parse_primary_key()))

        return super()._parse_column_constraint()

    def _parse_range(self, this: exp.Expr | None = None, parse_is: bool = False) -> exp.Expr | None:
        this = this or self._parse_bitwise()

        if self._match_text_seq("SOUNDS", "LIKE"):
            this = self.expression(
                exp.EQ(
                    this=self.expression(exp.Soundex(this=this)),
                    expression=self.expression(exp.Soundex(this=self._parse_bitwise())),
                )
            )
            # MySQL evaluates = and IS left to right because they have the same precedence.
            if self._match(TokenType.IS, advance=False):
                this = self.expression(exp.Paren(this=this))

        return super()._parse_range(this, parse_is=parse_is)

    def _parse_alter_table_rename(self):
        if self._match_texts(("INDEX", "KEY")):
            old = self._parse_id_var()
            self._match_text_seq("TO")
            new = self._parse_id_var()
            return self.expression(exp.RenameIndex(this=old, to=new))
        return super()._parse_alter_table_rename()

    def _parse_alter_drop_action(self) -> exp.Expr | None:
        if self._match_pair(TokenType.DROP, TokenType.PRIMARY_KEY):
            return self.expression(exp.DropPrimaryKey())
        if self._match_pair(TokenType.DROP, TokenType.KEY):
            return self._parse_drop(kind="INDEX")
        if self._match_text_seq("DROP", "CHECK"):
            return self._parse_drop(kind="CHECK")
        return super()._parse_alter_drop_action()

    def _parse_alter_table_modify(self, rename: bool = False) -> exp.Expr | None:
        # MODIFY [COLUMN]            col_name      column_definition [FIRST | AFTER col_name]
        # CHANGE [COLUMN] old_col_name new_col_name column_definition [FIRST | AFTER col_name]
        self._match(TokenType.COLUMN)

        column = self._parse_field(any_token=True)
        if column is None:
            return None

        rename_from = None
        if rename:
            rename_from = column
            column = self._parse_field(any_token=True)
            if column is None:
                return None

        column_def = self._parse_column_def(column)
        if not isinstance(column_def, exp.ColumnDef):
            return None

        return self.expression(exp.ModifyColumn(this=column_def, rename_from=rename_from))

    def _parse_generated_as_identity(
        self,
    ) -> (
        exp.GeneratedAsIdentityColumnConstraint
        | exp.ComputedColumnConstraint
        | exp.GeneratedAsRowColumnConstraint
    ):
        this = super()._parse_generated_as_identity()

        if self._match_texts(("STORED", "VIRTUAL")):
            persisted = self._prev.text.upper() == "STORED"

            if isinstance(this, exp.ComputedColumnConstraint):
                this.set("persisted", persisted)
            elif isinstance(this, exp.GeneratedAsIdentityColumnConstraint):
                this = self.expression(
                    exp.ComputedColumnConstraint(this=this.expression, persisted=persisted)
                )

        return this

    def _parse_primary_key_part(self) -> exp.Expr | None:
        this = self._parse_id_var()
        if not self._match(TokenType.L_PAREN):
            return this

        expression = self._parse_number()
        self._match_r_paren()
        return self.expression(exp.ColumnPrefix(this=this, expression=expression))

    def _parse_index_constraint_part(self) -> exp.Expr | None:
        # key_part: {col_name [(length)] | (expr)}, so only a prefixed column is followed by "("
        if (
            not self._match(TokenType.L_PAREN, advance=False)
            and self._next
            and self._next.token_type == TokenType.L_PAREN
        ):
            return self._parse_primary_key_part()

        return self._parse_disjunction()

    def _parse_index_key_part(self) -> exp.Expr | None:
        # Only keep the Ordered wrapper for an explicit ASC/DESC, otherwise the implicit
        # nulls_first leaks into other dialects as NULLS FIRST
        ordered = self._parse_ordered(self._parse_index_constraint_part)
        return ordered.this if ordered and ordered.args.get("desc") is None else ordered

    def _parse_index_constraint(self, kind: str | None = None) -> exp.IndexColumnConstraint:
        if kind:
            self._match_texts(("INDEX", "KEY"))

        this = self._parse_id_var(any_token=False)
        index_type = self._match(TokenType.USING) and self._advance_any() and self._prev.text
        expressions = self._parse_wrapped_csv(self._parse_index_key_part)

        return self.expression(
            exp.IndexColumnConstraint(
                this=this,
                expressions=expressions,
                kind=kind,
                index_type=index_type,
                options=self._parse_index_constraint_options(),
            )
        )

    def _parse_index_constraint_options(self) -> list[exp.IndexConstraintOption]:
        options = []
        while True:
            if self._match_text_seq("KEY_BLOCK_SIZE"):
                self._match(TokenType.EQ)
                opt = exp.IndexConstraintOption(key_block_size=self._parse_number())
            elif self._match(TokenType.USING):
                opt = exp.IndexConstraintOption(using=self._advance_any() and self._prev.text)
            elif self._match_text_seq("WITH", "PARSER"):
                opt = exp.IndexConstraintOption(parser=self._parse_var(any_token=True))
            elif self._match(TokenType.COMMENT):
                opt = exp.IndexConstraintOption(comment=self._parse_string())
            elif self._match_text_seq("VISIBLE"):
                opt = exp.IndexConstraintOption(visible=True)
            elif self._match_text_seq("INVISIBLE"):
                opt = exp.IndexConstraintOption(visible=False)
            elif self._match_text_seq("ENGINE_ATTRIBUTE"):
                self._match(TokenType.EQ)
                opt = exp.IndexConstraintOption(engine_attr=self._parse_string())
            elif self._match_text_seq("SECONDARY_ENGINE_ATTRIBUTE"):
                self._match(TokenType.EQ)
                opt = exp.IndexConstraintOption(secondary_engine_attr=self._parse_string())
            else:
                opt = None

            if not opt:
                break

            options.append(opt)

        return options

    def _parse_unique(self) -> exp.UniqueColumnConstraint:
        self._match_texts(("KEY", "INDEX"))
        this = self._parse_unique_key()
        index_type = self._parse_index_type()

        # UNIQUE [INDEX | KEY] [index_name] [index_type] (key_part,...) [index_option] ...
        if not self._match(TokenType.L_PAREN, advance=False):
            return self.expression(exp.UniqueColumnConstraint(this=this, index_type=index_type))

        expressions = self._parse_wrapped_csv(self._parse_index_key_part)

        return self.expression(
            exp.UniqueColumnConstraint(
                this=self.expression(exp.Schema(this=this, expressions=expressions)),
                index_type=index_type or self._parse_index_type(),
                options=self._parse_index_constraint_options(),
            )
        )

    def _parse_index_type(self) -> str | None:
        if self._match(TokenType.USING) and self._advance_any():
            return self._prev.text

        return None

    def _parse_show_mysql(
        self,
        this: str,
        target: bool | str = False,
        full: bool | None = None,
        global_: bool | None = None,
    ) -> exp.Show:
        json = self._match_text_seq("JSON")

        if target:
            if isinstance(target, str):
                self._match_text_seq(*target.split(" "))
            target_id = self._parse_id_var()
        else:
            target_id = None

        index = self._index
        if self._match_text_seq("IN"):
            log = self._parse_string()
            if log is None:
                self._retreat(index)
        else:
            log = None

        if this in ("BINLOG EVENTS", "RELAYLOG EVENTS"):
            position = self._parse_number() if self._match_text_seq("FROM") else None
            db = None
        else:
            position = None
            db = None

            if self._match(TokenType.FROM) or self._match_text_seq("IN"):
                db = self._parse_id_var()
            elif self._match(TokenType.DOT):
                db = target_id
                target_id = self._parse_id_var()

        channel = self._parse_id_var() if self._match_text_seq("FOR", "CHANNEL") else None

        like = self._parse_string() if self._match_text_seq("LIKE") else None
        where = self._parse_where()

        if this == "PROFILE":
            types = self._parse_csv(lambda: self._parse_var_from_options(self.PROFILE_TYPES))
            query = self._parse_number() if self._match_text_seq("FOR", "QUERY") else None
            offset = self._parse_number() if self._match_text_seq("OFFSET") else None
            limit = self._parse_number() if self._match_text_seq("LIMIT") else None
        else:
            types, query = None, None
            offset, limit = self._parse_oldstyle_limit()

        mutex = True if self._match_text_seq("MUTEX") else None
        mutex = False if self._match_text_seq("STATUS") else mutex

        for_table = self._parse_id_var() if self._match_text_seq("FOR", "TABLE") else None
        for_group = self._parse_string() if self._match_text_seq("FOR", "GROUP") else None
        for_user = self._parse_string() if self._match_text_seq("FOR", "USER") else None
        for_role = self._parse_string() if self._match_text_seq("FOR", "ROLE") else None
        into_outfile = self._parse_string() if self._match_text_seq("INTO", "OUTFILE") else None

        return self.expression(
            exp.Show(
                this=this,
                target=target_id,
                full=full,
                log=log,
                position=position,
                db=db,
                channel=channel,
                like=like,
                where=where,
                types=types,
                query=query,
                offset=offset,
                limit=limit,
                mutex=mutex,
                for_table=for_table,
                for_group=for_group,
                for_user=for_user,
                for_role=for_role,
                into_outfile=into_outfile,
                json=json,
                global_=global_,
            )
        )

    def _parse_oldstyle_limit(
        self,
    ) -> tuple[exp.Expr | None, exp.Expr | None]:
        limit = None
        offset = None
        if self._match_text_seq("LIMIT"):
            parts = self._parse_csv(self._parse_number)
            if len(parts) == 1:
                limit = parts[0]
            elif len(parts) == 2:
                limit = parts[1]
                offset = parts[0]

        return offset, limit

    def _parse_set_item_charset(self, kind: str) -> exp.Expr:
        this = self._parse_string() or self._parse_unquoted_field()
        return self.expression(exp.SetItem(this=this, kind=kind))

    def _parse_charset_name(self) -> exp.Expr | None:
        """
        Preserve quoting when a charset name has characters that require it (e.g. spaces, as allowed
        for custom XML-registered charsets). Safe names unwrap to a bare Var so roundtrips remain minimal.
        """
        identifier = self._parse_identifier()
        if identifier:
            return (
                exp.Var(this=name)
                if exp.SAFE_IDENTIFIER_RE.match(name := identifier.name)
                else identifier
            )
        return self._parse_var(tokens={TokenType.BINARY})

    def _parse_set_item_names(self) -> exp.Expr:
        charset = self._parse_string() or self._parse_unquoted_field()
        if self._match_text_seq("COLLATE"):
            collate = self._parse_string() or self._parse_unquoted_field()
        else:
            collate = None

        return self.expression(exp.SetItem(this=charset, collate=collate, kind="NAMES"))

    def _parse_type(
        self, parse_interval: bool = True, fallback_to_identifier: bool = False
    ) -> exp.Expr | None:
        # mysql binary is special and can work anywhere, even in order by operations
        # it operates like a no paren func
        if self._match(TokenType.BINARY, advance=False):
            data_type = self._parse_types(check_func=True, allow_identifiers=False)

            if isinstance(data_type, exp.DataType):
                return self.expression(exp.Cast(this=self._parse_column(), to=data_type))

        return super()._parse_type(
            parse_interval=parse_interval, fallback_to_identifier=fallback_to_identifier
        )

    def _parse_alter_table_alter_index(self) -> exp.AlterIndex:
        index = self._parse_field(any_token=True)

        if self._match_text_seq("VISIBLE"):
            visible = True
        elif self._match_text_seq("INVISIBLE"):
            visible = False
        else:
            visible = None

        return self.expression(exp.AlterIndex(this=index, visible=visible))

    def _parse_partition_property(
        self,
    ) -> exp.Expr | None | list[exp.Expr]:
        partition_cls: type[exp.Expr] | None = None
        value_parser = None

        if self._match_text_seq("RANGE"):
            partition_cls = exp.PartitionByRangeProperty
            value_parser = self._parse_partition_range_value
        elif self._match_text_seq("LIST"):
            partition_cls = exp.PartitionByListProperty
            value_parser = self._parse_partition_list_value

        if not partition_cls or not value_parser:
            return None

        partition_expressions = self._parse_wrapped_csv(self._parse_assignment)

        # For Doris and Starrocks
        if not self._match_text_seq("(", "PARTITION", advance=False):
            return partition_expressions

        create_expressions = self._parse_wrapped_csv(value_parser)

        return self.expression(
            partition_cls(
                partition_expressions=partition_expressions, create_expressions=create_expressions
            )
        )

    def _parse_partition_range_value(self) -> exp.Expr | None:
        self._match_text_seq("PARTITION")
        name = self._parse_id_var()

        if not self._match_text_seq("VALUES", "LESS", "THAN"):
            return name

        values = self._parse_wrapped_csv(self._parse_expression)

        if (
            len(values) == 1
            and isinstance(values[0], exp.Column)
            and values[0].name.upper() == "MAXVALUE"
        ):
            values = [exp.var("MAXVALUE")]

        part_range = self.expression(exp.PartitionRange(this=name, expressions=values))
        return self.expression(exp.Partition(expressions=[part_range]))

    def _parse_partition_list_value(self) -> exp.Partition:
        self._match_text_seq("PARTITION")
        name = self._parse_id_var()
        self._match_text_seq("VALUES", "IN")
        values = self._parse_wrapped_csv(self._parse_expression)
        part_list = self.expression(exp.PartitionList(this=name, expressions=values))
        return self.expression(exp.Partition(expressions=[part_list]))

    def _parse_foreign_key(self) -> exp.ForeignKey:
        # MySQL only uses this name when CONSTRAINT has none and no existing index fits
        this = (
            self._parse_id_var()
            if self._next and self._next.token_type == TokenType.L_PAREN
            else None
        )
        foreign_key = super()._parse_foreign_key()
        foreign_key.set("this", this)
        return foreign_key

    def _parse_primary_key(
        self,
        wrapped_optional: bool = False,
        in_props: bool = False,
        named_primary_key: bool = False,
    ) -> exp.PrimaryKeyColumnConstraint | exp.PrimaryKey:
        this = super()._parse_primary_key(
            wrapped_optional=wrapped_optional, in_props=in_props, named_primary_key=True
        )
        if isinstance(this, exp.PrimaryKey):
            # KEY_BLOCK_SIZE, COMMENT etc. after the key parts belong to the key, not the table
            this.set(
                "options",
                [*(this.args.get("options") or []), *self._parse_index_constraint_options()],
            )

        return this

